#!/usr/bin/env python3
"""immuno/mrna_vaccine_design — auto-generated run.py (archetype=mhc_epitope).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mhc_epitope"
BRAIN = "immuno"
SKILL = "mrna_vaccine_design"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'mrna_sequence': 'AUGUUCGUC...', 'codon_optimized_orf': 'AUGUUC...', 'utr_5p': 'GAGAAUAA...', 'utr_3p': 'AAGCUC...', 'polya': 'AAAA...', 'cai_human': 0.88, 'gc_pct': 56.0, 'mfe_kcal_per_mol': -425.0, 'has_m1psi_flag': True, 'cpg_count': 12, 'restriction_sites': [], 'cryptic_splice_count': 1, 'qc_pass': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """mRNA vaccine 设计:antigen aa → codon-optimize → 加 5' UTR + 3' UTR + polyA。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    aa = payload.get("antigen_sequence")
    species = payload.get("species", "human")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "species": species, "n_aa": len(aa) if aa else 0}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_epitopes": 0, "epitopes_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not aa:
        return {"ok": False, "error": "需要 antigen_sequence (蛋白序列)",
                "diagnostics": diagnostics}
    # 简化:人偏好密码子(每个 aa 取最高频 codon)
    human_codon = {"A": "GCC", "C": "TGC", "D": "GAC", "E": "GAG", "F": "TTC",
                  "G": "GGC", "H": "CAC", "I": "ATC", "K": "AAG", "L": "CTG",
                  "M": "ATG", "N": "AAC", "P": "CCC", "Q": "CAG", "R": "CGG",
                  "S": "AGC", "T": "ACC", "V": "GTG", "W": "TGG", "Y": "TAC",
                  "*": "TAA"}
    cds = "".join(human_codon.get(c.upper(), "NNN") for c in aa.upper()) + human_codon["*"]
    five_utr = "GGGAAAUAAGAGAGAAAAGAAGAGUAAGAAGAAAUAUAAGAGCCACC"  # 简化模板
    three_utr = "CUGCCUUCUGCGGGGCUUGCCUUCUGGCCAUGCCCUUCUUCUCUCCCUUGCACCUGUACCUCUUGGUCUUUGAAUAAAGCCUGAGUAGGAAG"
    poly_a = "A" * 120
    mrna = (five_utr + cds.replace("T", "U") + three_utr + poly_a)
    return {"ok": True, "skill_id": SKILL,
            "n_epitopes": 1, "epitopes_csv": "",
            "mrna_sequence": mrna, "cds_length": len(cds), "total_length": len(mrna),
            "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
